DO $$
DECLARE unknown int; moved int;
BEGIN
  SELECT count(*) INTO unknown FROM candidates c WHERE c.election_id IN ('a7b8c9d0-e1f2-3456-0123-678901232011', 'a7b8c9d0-e1f2-3456-0123-678901232016', 'a7b8c9d0-e1f2-3456-0123-678901232021')
    AND NOT EXISTS (SELECT 1 FROM kl_old_seed o WHERE o.id = c.id);
  SELECT count(*) INTO moved FROM candidates c JOIN kl_old_seed o ON o.id = c.id WHERE c.party_id IS DISTINCT FROM o.party_id;
  IF unknown > 0 OR moved > 0 THEN
    RAISE EXCEPTION 'seed_kl_corrections_v1: % Kerala candidates are not in the old seeds and % changed party since; reconcile them first (docs/DEPLOYMENT.md 5.0a)', unknown, moved;
  END IF;
END $$;

